CREATE TABLE patient_services ( id SERIAL PRIMARY KEY, patient_id INT NOT NULL REFERENCES patients(id) ON DELETE CASCADE, service_id INT NOT NULL REFERENCES services(id) ON DELETE CASCADE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (patient_id, service_id) ); CREATE INDEX idx_patient_services_patient_id ON patient_services(patient_id); CREATE INDEX idx_patient_services_service_id ON patient_services(service_id);